(*\:516d\:8282\:70b9\:4e09\:89d2\:5f62Lagrangian\:63d2\:503c\:5f62\:51fd\:6570*)
LagrangianShapeFuns[{\[Xi]_,\[Eta]_}]:={1/18 (-2+3 \[Eta]^2-3 \[Xi]+9 \[Xi]^2+Sqrt[3] \[Eta] (-1+6 \[Xi])),1/18 (-2+3 \[Eta]^2+3 \[Xi]+9 \[Xi]^2-Sqrt[3] \[Eta] (1+6 \[Xi])),1/9 (-1+Sqrt[3] \[Eta]+6 \[Eta]^2),1/9 (4-4 Sqrt[3] \[Eta]+3 \[Eta]^2-9 \[Xi]^2),2/9 (2-3 \[Eta]^2+3 \[Xi]+Sqrt[3] \[Eta] (1+3 \[Xi])),-(2/9) (-2+3 \[Eta]^2+3 \[Xi]+Sqrt[3] \[Eta] (-1+3 \[Xi]))};
LagrangianShapeFunsd\[Xi][{\[Xi]_,\[Eta]_}]:={-(1/6)+\[Eta]/Sqrt[3]+\[Xi],1/6-\[Eta]/Sqrt[3]+\[Xi],0,-2 \[Xi],2/3 (1+Sqrt[3] \[Eta]),-(2/3) (1+Sqrt[3] \[Eta])};
LagrangianShapeFunsd\[Eta][{\[Xi]_,\[Eta]_}]:={1/18 (6 \[Eta]+Sqrt[3] (-1+6 \[Xi])),1/18 (6 \[Eta]-Sqrt[3] (1+6 \[Xi])),1/9 (Sqrt[3]+12 \[Eta]),2/9 (-2 Sqrt[3]+3 \[Eta]),2/9 (-6 \[Eta]+Sqrt[3] (1+3 \[Xi])),-(2/9) (6 \[Eta]+Sqrt[3] (-1+3 \[Xi]))};


D0[E0_,v_]:=Module[{E1,v1,g22},
(*
E0\:8868\:793a\:5f39\:6027\:6a21\:91cf;
v\:8868\:793a\:6cca\:677e\:6bd4;
\:8fd4\:56de\:5404\:5411\:540c\:6027\:5f39\:6027\:4f53\:ff0c\:5f39\:6027\:5e38\:6570\:77e9\:9635\:ff1b
*)
E1=E0*(1-v)/((1+v)*(1-2v));
v1=v/(1-v);
g22=(1-2v)/(2*(1-v));
Return[E1*{
{1,v1,v1,0,0,0},
{v1,1,v1,0,0,0},
{v1,v1,1,0,0,0},
{0,0,0,g22,0,0},
{0,0,0,0,g22,0},
{0,0,0,0,0,g22}
}];
];


B1[gcoord_,gnum_,elementNo_,\[Xi]_,\[Eta]_]:=Module[
{m,r,ushape,ushaped\[Xi],ushaped\[Eta],vwshape,vwshaped\[Xi],vwshaped\[Eta],
NU,NUd\[Xi],NUd\[Eta],num,inode,ni,NU1,NU2,NU3,NU1d\[Xi],NU2d\[Xi],NU3d\[Xi],
NU1d\[Eta],NU2d\[Eta],NU3d\[Eta],pts,jac,ijac,NU1dy,NU1dz,NU2dy,NU2dz,NU3dy,NU3dz},
m=Length[gcoord];
num=gnum[[elementNo,;;]];
pts=gcoord[[num,;;]];
jac=jacob[pts,\[Xi],\[Eta]];
ijac=Inverse[jac];
r=ConstantArray[0.0,{6,10m}];

ushape=HermiteShapeFuns[{\[Xi],\[Eta]},pts];
ushaped\[Xi]=HermiteShapeFunsd\[Xi][{\[Xi],\[Eta]},pts];
ushaped\[Eta]=HermiteShapeFunsd\[Eta][{\[Xi],\[Eta]},pts];

vwshape=LagrangianShapeFuns[{\[Xi],\[Eta]}];
vwshaped\[Xi]=LagrangianShapeFunsd\[Xi][{\[Xi],\[Eta]}];
vwshaped\[Eta]=LagrangianShapeFunsd\[Eta][{\[Xi],\[Eta]}];

NU=ConstantArray[0.0,{3,5m}];
NUd\[Xi]=ConstantArray[0.0,{3,5m}];
NUd\[Eta]=ConstantArray[0.0,{3,5m}];

For[inode=1,inode<=6,inode++,
ni=num[[inode]];
NU[[1,5*(ni-1)+1;;5*(ni-1)+3]]=ushape[[3*inode-2;;3*inode]];
NU[[2,5*(ni-1)+4]]=vwshape[[inode]];
NU[[3,5*(ni-1)+5]]=vwshape[[inode]];

NUd\[Xi][[1,5*(ni-1)+1;;5*(ni-1)+3]]=ushaped\[Xi][[3*inode-2;;3*inode]];
NUd\[Xi][[2,5*(ni-1)+4]]=vwshaped\[Xi][[inode]];
NUd\[Xi][[3,5*(ni-1)+5]]=vwshaped\[Xi][[inode]];

NUd\[Eta][[1,5*(ni-1)+1;;5*(ni-1)+3]]=ushaped\[Eta][[3*inode-2;;3*inode]];
NUd\[Eta][[2,5*(ni-1)+4]]=vwshaped\[Eta][[inode]];
NUd\[Eta][[3,5*(ni-1)+5]]=vwshaped\[Eta][[inode]];
];
{NU1,NU2,NU3}=NU;
{NU1d\[Xi],NU2d\[Xi],NU3d\[Xi]}=NUd\[Xi];
{NU1d\[Eta],NU2d\[Eta],NU3d\[Eta]}=NUd\[Eta];

{NU1dy,NU1dz}=ijac . {NU1d\[Xi],NU1d\[Eta]};
{NU2dy,NU2dz}=ijac . {NU2d\[Xi],NU2d\[Eta]};
{NU3dy,NU3dz}=ijac . {NU3d\[Xi],NU3d\[Eta]};
r[[1,5m+1;;10m]]=NU1;
r[[2,1;;5m]]=NU2dy;
r[[3,1;;5m]]=NU3dz;
r[[4,1;;5m]]=NU2dz+NU3dy;
r[[5,1;;5m]]=NU1dz;
r[[5,5m+1;;10m]]=NU3;
r[[6,1;;5m]]=NU1dy;
r[[6,5m+1;;10m]]=NU2;
Return[{r,NU}];
];


mk0[E0_,v_,\[Rho]_,gauss_,gcoord_,gnum_]:=Module[{m,k,M,nu0,d,nels,iel,pts,i,\[Xi],\[Eta],w,y,z,jac,b1,NU,detJ},
(*
E0\:8868\:793a\:6750\:6599\:5f39\:6027\:6a21\:91cf
v\:8868\:793a\:6750\:6599\:6cca\:677e\:6bd4
\[Rho]\:8868\:793a\:6750\:6599\:5bc6\:5ea6
*)
m=Length[gcoord];
k=ConstantArray[0.0,{10m,10m}];(* \:622a\:9762\:521a\:5ea6\:7279\:6027\:77e9\:9635 *)
M=ConstantArray[0.0,{5m,5m}];(* \:622a\:9762\:8d28\:91cf\:7279\:6027\:77e9\:9635 *)
nu0=ConstantArray[0.0,{5m,3}];(* \:7b49\:6548\:8d28\:91cf\:5411\:91cf *)
d=D0[E0,v];
nels=Length[gnum];
For[iel=1,iel<=nels,iel++,
pts=gcoord[[gnum[[iel]],;;]];
For[i=1,i<=Length[gauss],i++,
{\[Xi],\[Eta],w}=gauss[[i,;;]];
jac=jacob[pts,\[Xi],\[Eta]];
{b1,NU}=B1[gcoord,gnum,iel,\[Xi],\[Eta]];
detJ=Det[jac];
k=k+b1\[Transpose] . d . b1*w*detJ;
M=M+\[Rho]*NU\[Transpose] . NU*w*detJ;
nu0=nu0+\[Rho]*NU\[Transpose]*w*detJ;
];
];
Return[{k,M,nu0}];
];


